SELECT CAST(MAKEDATE(YEAR(o.order_at), 1) + INTERVAL (QUARTER(o.order_at) - 1) QUARTER AS DATE) AS qq, SUM((SELECT COALESCE(SUM(amount_bdt), 0) FROM payments p WHERE p.order_id = o.order_id AND p.status = 'captured') - (SELECT COALESCE(SUM(amount_bdt), 0) FROM refunds r WHERE r.order_id = o.order_id)) FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2026-01-01 00:00:00' AND o.order_at < TIMESTAMP '2026-11-01 00:00:00' GROUP BY 1 ORDER BY 1
